"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Cygnus Expanse Gambit', 'author': 'Signature original', 'genre': 'Space Pirates', 'chapters': [{'n': 1, 'title': 'Launch', 'text': "In the hold, under work lights, Commander Dax Renn studied an alien engine core. It pulsed faintly, like a heart. 'light against the void,' Commander Dax Renn murmured. 'Let's find out what you are.'\n\nCommander Dax Renn gave the order anyway. The engines lit, the deck hummed, and the ship leapt toward an alien engine core with the Cygnus Expanse falling behind. Some cargoes, Commander Dax Renn knew, are worth the whole sky.\n\nThey grappled an alien engine core with the cargo arm as the first raider shells crossed their bow. Engineer Pip Solano whooped as the airlock sealed. Whatever an alien engine core was, it was theirs now — and Admiral Sarn knew it."}, {'n': 2, 'title': 'The Chart Unfolds', 'text': "They burned for the first waypoint with raiders on their tail. Commander Dax Renn flew the ship like a thrown knife, skimming a gravity well so close the hull sang. Behind them, Admiral Sarn's vanguard broke off, unwilling to follow.\n\n'It's a map,' breathed Commander Dax Renn, 'and a warning.' The route it drew cut through the worst of the drift: plasma storms, minefields, and the patrol lanes of Admiral Sarn.\n\nEngineer Pip Solano cracked an alien engine core's casing with a spanner and a prayer. Inside: coordinates, a starlog, a voice saying one word over and over — the name of the Cygnus Expanse."}, {'n': 3, 'title': 'Storm Season', 'text': "Through the fire they saw it: Admiral Sarn's flagship, waiting in the storm's eye like a spider. 'They knew the route,' Commander Dax Renn said. 'Someone sold the starlog.' The betrayal sat cold in their stomach.\n\nThe battle was short and ugly. Commander Dax Renn used the storm itself as a weapon, luring the flagship into a plasma surge that stripped its shields. They escaped in the glare, hull scorched, crew cheering raggedly.\n\nAfterward, Commander Dax Renn looked at each face on the bridge and said it plainly: 'There's a traitor aboard. I don't know who. But an alien engine core goes to the Cygnus Expanse — with all of us, or with whoever's left.'"}, {'n': 4, 'title': "The Traitor's Price", 'text': "Commander Dax Renn laughed for the first time in days. 'All this way,' they said, 'and we were carrying the lock, not the treasure.' Engineer Pip Solano was already calculating the wake-up sequence.\n\nCommander Dax Renn let them live, confined to quarters. 'Admiral Sarn trades in hostages,' Commander Dax Renn told the crew. 'We trade in something better.' It was a gamble; the crew's eyes said they knew it.\n\nEngineer Pip Solano caught them at the airlock. There was no fight — only the traitor crying that Admiral Sarn held their family. Commander Dax Renn understood, and hated understanding. Mercy, out here, was a luxury with teeth."}, {'n': 5, 'title': 'The Grid Awakens', 'text': "Silence, then. The grid humming. the Cygnus Expanse safe below. Engineer Pip Solano put a hand on Commander Dax Renn's shoulder and said what everyone was thinking: 'We live.'\n\nThe flagship came on anyway, and Commander Dax Renn met it ship to ship above the burning sky. It was Admiral Sarn themselves on the viewscreen, offering one last deal. Commander Dax Renn answered with the engines at full burn.\n\nEngineer Pip Solano fed an alien engine core into the ancient console. For a heartbeat nothing happened — then the sky caught fire, a lattice of light wrapping the Cygnus Expanse like a held breath. Admiral Sarn's vanguard shattered against it like waves on rock."}, {'n': 6, 'title': 'Home Signal', 'text': "And when the next distress call came — as it always does, out in the drift — the engines were already warm. There are always more skies. There is always the Cygnus Expanse, somewhere, needing its heroes.\n\nCommander Dax Renn stood on the hull at sunset, watching the Cygnus Expanse turn below. light against the void — the stars had taught it, and the crew had proved it, and the grid would remember it.\n\nThe traitor's family was found and freed; the traitor wept and was forgiven, and signed on again — this time for real. Commander Dax Renn's rule about second chances held, barely, and gloriously."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

